-- ============================================================
-- Kindred Pets — Business Data Store
-- Source: https://kindred-pets-store.myshopify.com/
-- Purpose: Raw structured data store for a future AI Agent
--          (customer support / product-recommendation agent)
-- Note: Prices/stock captured on scrape date; refresh periodically.
-- Scrape date: 2026-08-15
-- ============================================================

PRAGMA foreign_keys = ON;

-- ------------------------------------------------------------
-- 1. Company / Brand Info
-- ------------------------------------------------------------
DROP TABLE IF EXISTS company_info;
CREATE TABLE company_info (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    brand_name      TEXT NOT NULL,
    tagline         TEXT,
    description     TEXT,
    website_url     TEXT,
    founded_story   TEXT,
    address         TEXT,
    phone           TEXT,
    whatsapp_number TEXT,
    whatsapp_link   TEXT,
    email           TEXT,
    support_hours   TEXT,
    instagram_url   TEXT,
    youtube_url     TEXT,
    facebook_url    TEXT,
    welcome_code    TEXT,
    welcome_discount TEXT
);

    brand_name, tagline, description, website_url, founded_story,
    address, phone, whatsapp_number, whatsapp_link, email,
    support_hours, instagram_url, youtube_url, facebook_url,
    welcome_code, welcome_discount
) VALUES (
    'Kindred Pets',
    'Comfort and connection for the pets who share our lives.',
    'Kindred Pets is an everyday-essentials pet store offering thoughtfully selected pet accessories for walks, play, rest, feeding, and everyday care. Clear product information, transparent policies, and a straightforward way to shop. The store covers Dog Walking Essentials, Dog & Cat Toys, Grooming & Health, Pet Beds & Comfort, Feeding & Litter Supplies, and Pet Travel & Outdoor Gear.',
    'https://kindred-pets-store.myshopify.com',
    'Kindred Pets was built around a simple idea: life with a pet should feel less like work and more like companionship. The brand focuses on everyday essentials — the kind of small, well-made items owners reach for daily — without inflated claims or mystery promises.',
    'Online-only Shopify store (ships internationally from fulfillment partners)',
    '+1 (via Shopify checkout support)',
    '+1 (via Shopify checkout support)',
    'https://kindred-pets-store.myshopify.com/pages/contact',
    'support via Shopify Contact form',
    'Mon–Fri, 9 AM–6 PM (store timezone)',
    'https://www.instagram.com/',
    'https://www.youtube.com/',
    'https://www.facebook.com/',
    'WELCOME15',
    '15% off first order'
);

-- ------------------------------------------------------------
-- 2. Product Categories (Collections)
-- ------------------------------------------------------------
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    name         TEXT NOT NULL UNIQUE,
    slug         TEXT NOT NULL,
    description  TEXT
);


-- ------------------------------------------------------------
-- 3. Products
-- ------------------------------------------------------------
DROP TABLE IF EXISTS products;
CREATE TABLE products (
    id                  INTEGER PRIMARY KEY,
    name                TEXT NOT NULL,
    slug                TEXT UNIQUE NOT NULL,
    url                 TEXT,
    category            TEXT,
    description         TEXT,
    product_type        TEXT,
    tags                TEXT,
    primary_image_url   TEXT,
    base_price_usd      REAL,
    mrp_usd             REAL,
    is_active           INTEGER DEFAULT 1,
    in_stock            INTEGER DEFAULT 1
);


-- ------------------------------------------------------------
-- 4. Product Variants
-- ------------------------------------------------------------
DROP TABLE IF EXISTS product_variants;
CREATE TABLE product_variants (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id      INTEGER NOT NULL,
    variant_label   TEXT,
    sku             TEXT,
    price_usd       REAL,
    in_stock        INTEGER,
    availability    TEXT,
    FOREIGN KEY (product_id) REFERENCES products(id)
);


-- ------------------------------------------------------------
-- 5. FAQs
-- ------------------------------------------------------------
DROP TABLE IF EXISTS faqs;
CREATE TABLE faqs (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    category    TEXT,
    question    TEXT NOT NULL,
    answer      TEXT NOT NULL
);

 'We sell everyday pet accessories across six core collections: Dog Walking Essentials (collars, leashes, harnesses, treat pouches, waste scoops), Dog & Cat Toys (laser toys, fetch launchers, chew toys), Grooming & Health (brushes, nail grinders, shampoos, ear cleansers, paw washers), Pet Beds & Comfort (memory-foam beds, cooling mats, cat trees, hammocks, cozy nests), Feeding & Litter Supplies (automatic feeders, slow feeder bowls, oversized bowls, litter odor eliminators), and Pet Travel & Outdoor Gear (car seat covers, travel backpacks, foldable waste scoops).'),

('Product & Quality', 'Where do Kindred Pets products ship from?',
 'Items ship from international fulfillment partners. Each product page notes the shipping window — most items ship in 1–2 business days and arrive within 7–15 business days depending on destination.'),

('Product & Quality', 'Are the products safe for both dogs and cats?',
 'Most items specify which species they are designed for on the product page. Items like the nail grinder, paw washer, tear-stain wipes, ear cleanser, and cooling mat are explicitly designed for both dogs and cats. Always read the product page before ordering for a specific pet.'),

('Product & Quality', 'What materials are used?',
 'Common materials across the catalog include food-grade silicone (brushes, bowls), durable 600D Oxford cloth (car seat covers, treat pouches), arctic velvet (cat nests), textured leather (LED collars), and ABS plastic (toys). Each product page lists the specific materials and care instructions.'),

('Ordering & Payment', 'How do I place an order?',
 'Add the product to your cart, click checkout, and follow the secure Shopify checkout flow. You can pay with American Express, Apple Pay, Bancontact, Diners Club, Discover, Google Pay, Mastercard, Shop Pay, or Visa.'),

('Ordering & Payment', 'Do you have a first-order discount?',
 'Yes. Use code WELCOME15 at checkout to get 15% off your first order. The code is valid once per customer and applies to the order subtotal before tax and shipping.'),

('Ordering & Payment', 'Can I modify or cancel my order after placing it?',
 'Because the store uses fast fulfillment, changes are hard to make once an order is placed. If you need to change or cancel, reach out through the Shopify contact form as quickly as possible and the team will do their best to help before the order ships.'),

('Shipping & Delivery', 'How long does shipping take?',
 'Most items ship in 1–2 business days and arrive in 7–15 business days, depending on your country and the carrier. Tracking is provided by email once the order is dispatched.'),

('Shipping & Delivery', 'Do you ship internationally?',
 'Yes — the store ships to many countries, with multi-region plug adapters available on the Smart Feed Pro listing. Shipping costs and delivery times are calculated at checkout based on your address.'),

('Shipping & Delivery', 'How can I track my order?',
 'Use the Track Your Order link in the top navigation. You will need your order number and the email used at checkout. If you cannot find tracking details, reach out via the store contact form.'),

('Returns & Refunds', 'What is the return policy?',
 'Because the store emphasizes clear product information up front, returns are handled on a case-by-case basis. If a product arrives damaged, defective, or not as described, contact the store through the contact form within the standard return window and the team will work with you on a replacement or refund.'),

('Returns & Refunds', 'What if my item arrives damaged?',
 'Sorry to hear that. Please reach out via the store contact form with your order number and a photo of the damage, and the team will arrange a replacement or refund as quickly as possible.'),

('Returns & Refunds', 'Can I return a used item?',
 'For hygiene reasons, used grooming items, opened food/water bowls, and worn pet beds are generally not eligible for return unless they arrived damaged or defective. Unused, unopened items in original packaging are more likely to qualify — contact the store to confirm.'),

('Customer Support', 'How do I contact customer support?',
 'Use the Contact link in the store footer or top navigation. The team aims to respond within one business day. Support hours are Mon–Fri, 9 AM–6 PM in the store timezone.'),

('Customer Support', 'Do you offer sizing help for harnesses and collars?',
 'Yes. Each harness, collar, and leash product page lists available sizes (S / M / L / XL) and what measurements they fit. If you are unsure, message the team with your pet''s neck girth or weight and they will recommend the right size.'),

('Customer Support', 'Are your products suitable for puppies and kittens?',
 'Several items are explicitly designed for smaller or younger pets — the slow feeder bowl, the clicker & whistle bracelet, the cooling mat, and the plush pet bed are all good starter picks. For chew toys, always supervise play and pick a size appropriate for your puppy.');

-- ------------------------------------------------------------
-- 6. Policies (synthesized from homepage + product shipping notes)
-- ------------------------------------------------------------
DROP TABLE IF EXISTS policies;
CREATE TABLE policies (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL,
    description TEXT
);

 'Most items ship within 1–2 business days and arrive in 7–15 business days. International shipping is available; costs and delivery times are calculated at checkout. Tracking is emailed once the order is dispatched. Multi-region plug adapters (US, EU, UK, AU, JP, KR, CN) are available on the Smart Feed Pro listing.'),

('Returns & Refunds Policy',
 'Returns are handled case-by-case. Unused, unopened items in original packaging are most likely to qualify. Used grooming items, opened food/water bowls, and worn pet beds are generally not eligible for return unless they arrived damaged or defective. If something arrives damaged or not as described, contact the store within the standard return window with your order number and a photo.'),

('Privacy Policy',
 'The store uses Shopify''s standard privacy infrastructure. Customer information (name, shipping address, email, payment details) is used only to process and ship orders, send tracking updates, and respond to support requests. Payment data is handled by Shopify Payments and never stored on Kindred Pets servers.'),

('Terms of Service',
 'By placing an order you agree to provide accurate shipping and payment information, to use the products only for their intended pet-care purpose, and to follow the safety and care directions listed on each product page. Prices and availability are subject to change without notice.'),

('WELCOME15 Discount',
 'First-order customers can use code WELCOME15 at checkout for 15% off the order subtotal, before tax and shipping. The code is valid once per customer and cannot be combined with other promotions.');

-- ------------------------------------------------------------
-- 7. Site pages
-- ------------------------------------------------------------
DROP TABLE IF EXISTS site_pages;
CREATE TABLE site_pages (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    page_name TEXT NOT NULL,
    url       TEXT NOT NULL
);

