INSERT INTO products (id, name, slug, url, category, description, product_type, tags, primary_image_url, base_price_usd, mrp_usd, is_active, in_stock) VALUES
(8063360630874, 'Kindred Motion Laser Cat Toy', 'interactive-laser-cat-toy', 'https://kindred-pets-store.myshopify.com/products/interactive-laser-cat-toy', 'Dog & Cat Toys', 'Give indoor cats something worth chasing. This automatic laser toy keeps play moving with timed sessions, giving your cat an easy way to stay curious and engaged while you''re busy. Made for everyday play Automatic timed play sessions Designed for indoor cats Compact and easy to place around the home Laser play should be supervised and should never be directed toward people or animals'' eyes. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Toys', 'automatic cat toy, cat entertainment device, indoor cat exercise, interactive cat toy, laser cat toy', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/42eeea05432cb9d5fe06b0bd938f.png?v=1786750713', 19.99, 19.99, 1, 1),
(8059730591834, 'Training Dog Treat Pouch', 'training-dog-treat-pouch', 'https://kindred-pets-store.myshopify.com/products/training-dog-treat-pouch', 'Training & Behavior', 'Training goes better when treats are always within reach. This zippered pouch clips to your belt or bag, keeping treats close and accessible for consistent, well-timed rewards during every session. Why it works Quick zipper access for fast reward timing Durable 600D Oxford cloth resists wear Compact enough for pockets, belts, or bags Built for regular use at home or on walks Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Training & Behavior', 'dog treat pouch, outdoor training gear, Oxford cloth treat bag, training accessory, zippered treat pouch', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/5b039e00498ba3834ee39abb8556.jpg?v=1786750710', 7.99, 7.99, 1, 1),
(8055073865818, 'Rechargeable LED Glow Leather Dog Collar', 'led-glow-pet-collar-with-light-up-features', 'https://kindred-pets-store.myshopify.com/products/led-glow-pet-collar-with-light-up-features', 'Dog Walking Essentials', 'Give evening walks a safety upgrade without sacrificing style. This rechargeable LED glow collar pairs textured leather with a built-in light strip, so your dog stays comfortable, stylish, and visible after dark. A single charge powers the glow strip for hours of use, and the soft leather is finished with a subtle carved texture for a polished look day or night. Available in Black, Blue, Red, and Green, in Small, Medium, and Large. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Collars & Leashes', 'leather LED collar, LED dog collar, light up dog collar, night safety dog collar, rechargeable glow collar', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/e4a719484df4b434aa38655cfe44.jpg?v=1786064084', 8.99, 8.99, 1, 1),
(8054932308058, 'Kindred Quiet Nail Grinder', 'rechargeable-electric-pet-nail-polisher-with-leds', 'https://kindred-pets-store.myshopify.com/products/rechargeable-electric-pet-nail-polisher-with-leds', 'Grooming & Health', 'Make nail care feel more manageable. This rechargeable pet nail grinder gives you a controlled alternative to traditional clippers, with an LED light to help you see the trimming area more clearly. Made for at-home grooming Rechargeable design Built-in LED light Designed for dogs and cats Introduce the grinder gradually and follow the product instructions. Trim carefully and stop if your pet becomes uncomfortable. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat nail care, dog nail care, LED nail grinder, pet nail grinder, quiet pet grooming tool, rechargeable nail trimmer', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/85c0700a47db8c16e73de1d66083.jpg?v=1786064083', 27.99, 27.99, 1, 1),
(8054931062874, 'Kindred Motion Ball — USB Interactive Dog Toy', 'smart-interactive-dog-toy-ball-with-usb-charging-one-piece', 'https://kindred-pets-store.myshopify.com/products/smart-interactive-dog-toy-ball-with-usb-charging-one-piece', 'Dog & Cat Toys', 'A self-moving ball for dogs who love to chase. The Kindred Motion Ball rolls and bounces on its own to encourage active indoor play. Recharge it by USB and let your dog chase, nudge, and follow the movement. Choose carefully Complete Dog Jump Ball: the complete playable toy. Replacement Shell: replacement outer shell only. It is not the complete toy. First purchase? Choose the Complete Dog Jump Ball . Before you order Choose Blue or Orange. Supervise play and inspect the toy regularly. Remove the toy if it becomes damaged or pieces become loose. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Toys', 'automatic bouncing ball, dog exercise toy, interactive dog toy, smart pet toy, USB rechargeable dog toy', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/8e2c179749a7abe50a20935dc64a.png?v=1786064083', 5.99, 5.99, 1, 1),
(8054925819994, 'Two-in-One Training Clicker & Whistle Bracelet', 'two-in-one-pet-training-clicker-and-whistle-bracelet', 'https://kindred-pets-store.myshopify.com/products/two-in-one-pet-training-clicker-and-whistle-bracelet', 'Training & Behavior', 'Clear communication is the foundation of good training. This two-in-one clicker and whistle bracelet keeps both tools on your wrist, so you''re always ready to mark good behavior the moment it happens. Built from durable plastic with a comfortable, adjustable band, it''s designed for daily use on walks, at the park, or in the backyard. No fumbling through pockets — just click, whistle, and reward. Available in 11 colors to match your style. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Training & Behavior', 'dog training clicker, obedience training, pet training tool, positive reinforcement training, whistle bracelet', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/44ee00a64e859e10a1c7e4113ccd.jpg?v=1786064079', 1.99, 1.99, 1, 1),
(8054921723994, 'Kindred Wall-Mounted Cat Grooming Brush', 'cat-self-grooming-brush', 'https://kindred-pets-store.myshopify.com/products/cat-self-grooming-brush', 'Grooming & Health', 'A simple self-grooming spot your cat can use on their own. This wall-mounted brush gives cats a place to rub and scratch while helping loosen excess fur. A built-in catnip compartment can make the brush more inviting, and the removable brush is designed for easier cleaning. Choose your version Standard: the individual brush in the selected color. Large: a larger brush option where available. 2-Pack: two brushes for customers who want more than one grooming spot. Before you order Check the selected size and pack quantity before adding to cart. Choose the color you prefer. Install the brush on a suitable surface and check that it is secure before allowing your cat to use it. Inspect the brush regularly and replace it if damaged. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat massage brush, cat scratching brush, cat self groomer, catnip grooming toy, wall mounted cat brush', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/f98b01a24a369df63a1e1680fe82.png?v=1786064072', 9.99, 16.99, 1, 1),
(8054916317274, 'Kindred Cooling Pet Mat — Self-Cooling Summer Bed', 'cooling-pet-mat-ice-silk-summer-bed', 'https://kindred-pets-store.myshopify.com/products/cooling-pet-mat-ice-silk-summer-bed', 'Pet Beds & Comfort', 'A simple, portable place for your pet to settle on warm days. This lightweight cooling mat is designed for everyday use at home or on the go. The self-cooling surface provides a cooler resting spot without refrigeration or electricity. Why it fits everyday summer use Self-cooling surface with no power required Lightweight and easy to move between rooms, crates, cars, or patios Multiple sizes for small pets through larger dogs Multiple colors available Choose the right size Measure your pet and compare those measurements with the selected mat dimensions before ordering. Choose based on the space your pet actually needs rather than breed alone. 40 × 30 cm: small cats and toy-sized pets 50 × 40 cm / 62 × 50 cm: cats and smaller dogs 70 × 55 cm: medium dogs 100 × 70 cm / 150 × 100 cm: larger dogs or shared resting areas Before you order Cooling products are not a substitute for shade, water, ventilation, or veterinary care in hot weather. Always supervise your pet and move them to a cooler environment if they show signs of overheating. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Beds & Comfort', 'cat cooling mat, cooling pet mat, ice silk pet mat, self-cooling pet bed, summer dog bed, washable pet mat', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/2b4c6a6a4ef2b71e7bf93dad576e.png?v=1786064071', 2.99, 19.99, 1, 1),
(8027341914202, 'Kindred Foldaway Waste Scoop', 'foldable-dog-pet-travel-poop-scoop', 'https://kindred-pets-store.myshopify.com/products/foldable-dog-pet-travel-poop-scoop', 'Pet Travel & Outdoor Gear', 'Cleanup shouldn''t be the part of the walk you dread. This foldable waste scoop makes pickup quick and convenient, then collapses for easy storage in a bag or car. Made for everyday walks Folds down for compact storage Designed for quick, one-motion pickup Easy to keep in your walking kit Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Travel & Outdoor Gear', 'dog walking essential, easy clean scooper, foldable dog waste tool, portable poop scoop, travel pet cleanup', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/973e7798453cbb5a98a9c08f7c26.jpg?v=1785000643', 14.99, 14.99, 1, 1),
(8027285848154, 'Kindred Smart Feed Pro — Scheduled Feeding, Made Simple', 'smart-feed-pro', 'https://kindred-pets-store.myshopify.com/products/smart-feed-pro', 'Feeding & Litter Supplies', 'Mealtime, made more dependable. Kindred Smart Feed Pro dispenses portioned meals on a schedule you control, helping your pet stay on routine even when work, travel, or a late night gets in the way. Why you''ll love it WiFi-connected scheduling for convenient feeding Portion control for more consistent meals Designed for dogs and cats Useful peace of mind when you''re away from home Kindred Standard Thoughtful technology for everyday pet care. Select the correct power configuration for your region before ordering. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Feeding & Litter Supplies', 'automatic pet feeder, dog and cat feeder, portion control feeder, smart feeding schedule, WiFi pet feeder', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/smart-feed-pro-ad.png?v=1786064070', 59.99, 59.99, 1, 1),
(8027023966298, 'Kindred Cozy Cat Tunnel & Bed', 'cat-tunnel-cat-bed-cat-mat-cat-sleeping-bag', 'https://kindred-pets-store.myshopify.com/products/cat-tunnel-cat-bed-cat-mat-cat-sleeping-bag', 'Pet Beds & Comfort', 'One cozy space. Four ways to use it. This flexible cat set can be arranged as a tunnel, nest, mat, or sleeping bag—giving your cat a comfortable place to hide, play, and settle down. Made for everyday comfort Four configurations for play and rest Soft, cozy construction Easy to rearrange around the home Ships in 1–2 business days · Arrives in 7–15 business days.', 'Cat Beds', '4-in-1 cat sleeping set, cat nest and tunnel, cat tunnel bed, cozy cat mat, multi-use cat bed', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/0cca959e4a89a882cd6a18825165.png?v=1785000594', 21.99, 21.99, 1, 1),
(8027023736922, 'Kindred Cat Climber — 170 cm Multi-Level Cat Tree', 'cat-climber-cat-house', 'https://kindred-pets-store.myshopify.com/products/cat-climber-cat-house', 'Pet Beds & Comfort', 'Give your cat a dedicated place to climb, scratch, perch, and play. The Kindred Cat Climber uses vertical space to create multiple levels for climbing and resting, giving curious cats a place of their own instead of relying on shelves and furniture. What you''re getting 170 cm tall: a substantial vertical setup for cats who enjoy climbing. 50 × 50 cm footprint: check your available floor space before ordering. Multiple levels: more than one place to climb and perch. Dark grey finish: the current configuration is offered in dark grey. Before you order Measure the intended area first and make sure you have enough clearance around the climber. Assemble it according to the included instructions and check that it is stable before allowing your cat to use it. Best for: cat owners who want to add vertical play and resting space without giving up another room. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Cat Furniture', 'cat activity center, cat play house, cat tree climber, climbing frame for cats, large cat tree', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/7535897741dc895ad304894e22cc.webp?v=1784966889', 69.99, 69.99, 1, 1),
(8026763657306, 'Kindred Support Memory Foam Dog Bed', 'urpet-orthopedic-dog', 'https://kindred-pets-store.myshopify.com/products/urpet-orthopedic-dog', 'Pet Beds & Comfort', 'A supportive, comfortable place for smaller dogs to rest. The Kindred Support Memory Foam Dog Bed combines a cushioned memory-foam base with a washable, water-resistant cover for everyday lounging and sleep. Why it may be worth the upgrade Memory foam cushioning for a more supportive resting surface. Washable cover for easier everyday care. Water-resistant cover to help protect the bed from everyday messes. 5.7-inch listed thickness gives the bed a substantial, cushioned profile. Before you order This listing is sized at 25 × 20 × 5.7 inches . Compare those measurements with your dog''s sleeping position and available space before ordering. The current variant is Grey. This bed is intended for comfort and rest. It is not a medical device and should not be relied on to diagnose, treat, or prevent a medical condition. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Beds & Comfort', 'joint support dog bed, memory foam pet bed, orthopedic dog bed, small dog sleeping mat, waterproof washable bed', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/aiblog-6a752bac42d4b7.24655023.png?v=1786750701', 89.99, 89.99, 1, 1),
(8026070941786, 'Tear Stain Eye Wipes for Dogs & Cats (120 Pads)', 'cat-dog-eye-wash-wip', 'https://kindred-pets-store.myshopify.com/products/cat-dog-eye-wash-wip', 'Grooming & Health', 'Tear stains show up faster than most owners can keep up with. These gentle wipes clean around sensitive eye areas, helping reduce stains and irritation for dogs and cats prone to watery eyes. Why it works Gentle formula safe for daily use near eyes Helps reduce visible tear stains over time Convenient pre-moistened pads, no rinsing needed 120-count pack lasts through regular use Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat eye cleaner, conjunctivitis eye pads, dog eye wipes, gentle eye cleaning wipes, tear stain remover', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/48958c024a69939e681e5022b7c5.jpg?v=1785000591', 24.99, 24.99, 1, 1),
(8024276697178, 'Kindred Car Seat Cover — Waterproof Pet Travel Protector', 'dog-car-seat-cover-waterproof-pet-mat', 'https://kindred-pets-store.myshopify.com/products/dog-car-seat-cover-waterproof-pet-mat', 'Pet Travel & Outdoor Gear', 'Protect your car from fur, dirt, muddy paws, and everyday mess. The Kindred Car Seat Cover creates a protective barrier between your pet and your vehicle, making everyday rides and longer road trips easier to clean up after. Why it earns its place in the car Waterproof protection helps shield the seat from spills and wet messes. Full-coverage design helps contain fur, dirt, and debris during travel. Built for repeat use so you can leave it ready for everyday pet trips. Before you order Check your vehicle''s seat dimensions and attachment points against the product images and specifications before ordering. Choose Black or Gray —both variants are the same product. Best for: pet owners who want an easier-to-clean vehicle setup for regular rides. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Travel & Outdoor Gear', 'car seat pet mat, dog car protector, Oxford cloth pet mat, travel seat cover for dogs, waterproof car seat cover', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/54cd19274073970ce005bf9e244a.jpg?v=1785000588', 59.99, 59.99, 1, 1),
(8022796238938, 'Laser Teaser Cat Collar', 'pet-laser-cat-teasing-collar-one-piece', 'https://kindred-pets-store.myshopify.com/products/pet-laser-cat-teasing-collar-one-piece', 'Dog & Cat Toys', 'Some cats need to chase something, even when you''re busy. This wearable collar projects a laser your cat can chase hands-free, turning idle moments into playtime without you holding anything. Why it works Hands-free play while you''re occupied elsewhere Encourages exercise for indoor cats Lightweight and comfortable to wear Simple on/off control Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Toys', 'cat entertainment device, indoor cat exercise, interactive cat toy, laser cat collar, wearable laser toy', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/79df01e64f92a879a46611e450be.png?v=1785000584', 13.99, 13.99, 1, 1),
(8022796107866, 'Fur Cleaning Needle Comb', 'pet-grooming-needle-comb-for-cleaning-fur-single-piece', 'https://kindred-pets-store.myshopify.com/products/pet-grooming-needle-comb-for-cleaning-fur-single-piece', 'Grooming & Health', 'Undercoat doesn''t come out with just any comb. Fine needle teeth reach past the topcoat to gently pull out loose, tangled fur — the kind that regular brushing tends to miss. Why it works Reaches undercoat without pulling on skin Reduces matting before it starts Works on both cats and dogs Easy to clean between uses Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat and dog grooming comb, deshedding comb, fur detangling tool, needle comb for pets, undercoat brush', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/039d8f034fbebbe4a9877e6201a0.png?v=1785000584', 6.99, 6.99, 1, 1),
(8019066290266, 'Pet Shampoo Brush and Massage Comb', 'pet-shampoo-brush-and-massage-comb', 'https://kindred-pets-store.myshopify.com/products/pet-shampoo-brush-and-massage-comb', 'Grooming & Health', 'Pamper your furry friend with this soft silicone pet shampoo brush and massage comb. Perfect for grooming and bathing cats or dogs with short hair, it combines gentle scrubbing with a built-in 80ml dispenser for easy application. A must-have for pet care! Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat massage brush, dog shampoo brush, grooming and bathing tool, short hair pet brush, silicone bath brush', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/224f624f4a4e8e014dabe88cfdbe.png?v=1785000573', 4.99, 4.99, 1, 1),
(8018189779034, 'Kindred Gentle Pet Ear Cleanser', 'pet-ear-cleaner-50ml', 'https://kindred-pets-store.myshopify.com/products/pet-ear-cleaner-50ml', 'Grooming & Health', 'A simple part of a cleaner grooming routine. This 50 ml pet ear-cleaning solution is designed for routine external ear hygiene for dogs and cats. Made for everyday care 50 ml bottle Designed for dogs and cats For routine external ear cleaning Follow the product directions. Do not use inside the ear canal or on irritated or injured skin. If your pet has persistent ear problems, consult a veterinarian. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat ear cleaner, dog and cat ear care, dog ear cleaning solution, ear infection prevention pets, ear mite treatment pets, gentle pet ear wash, pet ear cleaner, pet health and hygiene, pet hygiene liquid, safe ear cleanser for pets', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/70c45adb4816b3e82547b84eb098.jpg?v=1785000543', 6.99, 6.99, 1, 1),
(8018187485274, 'Disposable Pet Gloves & Eye Wipes', 'pet-cleaning-gloves-wipes', 'https://kindred-pets-store.myshopify.com/products/pet-cleaning-gloves-wipes', 'Grooming & Health', 'Keep your pets fresh and comfortable with our Pet Cleaning Gloves & Wipes , designed for safe and hassle-free hygiene. Choose from disposable gloves, extra-thick cleaning gloves, tooth wipes, ear wipes, eye wipes, or foot-cleaning foam—each option made to gently clean and care for your cat or dog. Individually packaged for maximum freshness and convenience, these essentials make grooming and daily care simple and stress-free for both you and your pet. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'cat grooming essentials, disposable pet gloves, dog cleaning wipes, gentle pet cleaner, pet care wipes, pet cleaning wipes, pet grooming wipes, pet hygiene wipes', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/b8a1b2724b539f4557e9d0a90d26.png?v=1785000537', 5.99, 5.99, 1, 1),
(8018186731610, 'Kindred Auto Double Dog Leash', 'auto-double-dog-leash', 'https://kindred-pets-store.myshopify.com/products/auto-double-dog-leash', 'Dog Walking Essentials', 'Two dogs, one easier walk. This telescopic double leash keeps both dogs connected to a single handle, helping make walks with two dogs simpler and more manageable. Made for everyday walks Double-leash design Telescopic lead system Available in multiple colors Ships in 1–2 business days · Arrives in 7–15 business days.', 'Dog Collars and Leashes', 'automatic retractable leash, double dog leash, reflective night walking leash, telescopic leash with light, walk two dogs leash', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/c3aaf87d46e08a1ccbb1abf39f1e.png?v=1785000537', 16.99, 16.99, 1, 1),
(8018184831066, 'Pet Odor Eliminator for Litter Boxes', 'pet-odor-eliminator-for-litter-boxes', 'https://kindred-pets-store.myshopify.com/products/pet-odor-eliminator-for-litter-boxes', 'Feeding & Litter Supplies', 'A litter box can be spotless and still smell like a litter box. This compact deodorizer uses sterilizing, odor-neutralizing technology to keep the air around it fresh between scoops — not just masked. Why it works Neutralizes odor at the source, not just perfume-covers it USB-powered for easy placement anywhere Compact enough for small litter areas Keeps shared spaces more livable Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Feeding & Litter Supplies', 'fresh litter box, litter box deodorizer, odor eliminator for cats, sterilizing litter tool, USB odor control', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/4fd6b4244bc08936376f73090bb9.png?v=1785000533', 14.99, 14.99, 1, 1),
(8018183520346, 'Kindred Pet Hair Carpet Broom', 'pet-hair-removal-broom-mop', 'https://kindred-pets-store.myshopify.com/products/pet-hair-removal-broom-mop', 'Pet accessories', 'Lift stubborn pet hair from carpets and rugs without the usual frustration. The Kindred Pet Hair Carpet Broom uses textured bristles to loosen embedded fur from carpet and rug fibers, making shedding cleanup easier between deeper cleans. Why it''s useful Textured bristles help pull loose and embedded pet hair from carpet surfaces. Made for shedding cleanup when a vacuum alone doesn''t get everything. Simple everyday tool for pet owners dealing with regular fur buildup. Choose your color Available colors use the same product and price. Choose the finish you prefer. Tip: Test on a small area first, especially on delicate rugs or unusual carpet materials. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet accessories', 'carpet pet hair tool, fur removal mop, home cleaning for pet owners, pet hair broom, shedding cleanup broom', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/9a93d0ff4f478786a3f80b4e850b.png?v=1785000531', 7.99, 7.99, 1, 1),
(8017470685274, 'Transparent Bubble Window Pet Travel Backpack', 'transparent-portable-pet-outing-space-capsule-backpack', 'https://kindred-pets-store.myshopify.com/products/transparent-portable-pet-outing-space-capsule-backpack', 'Pet Travel & Outdoor Gear', 'Some pets get anxious the second they can''t see out. A clear bubble window lets your cat or small dog watch the world go by, so trips outside feel like an adventure instead of a shutdown. Why it works Clear window keeps anxious pets calmer in transit Breathable panels prevent overheating Padded straps for comfortable everyday carrying Compact enough for errands, transit, or short flights Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Travel & Outdoor Gear', 'bubble window backpack, cat travel backpack, clear pet carrier, dog outing carrier, space capsule pet bag', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/69c4a7b24400a8bbcb363225163a.png?v=1785000526', 14.99, 14.99, 1, 1),
(8003767763034, 'Pet Electric Paw Washer – Portable Muddy Foot Cleaner', 'pet-electric-foot-washer', 'https://kindred-pets-store.myshopify.com/products/pet-electric-foot-washer', 'Grooming & Health', 'Muddy paws shouldn''t mean a fight at the front door. This portable washer gently cleans paws after walks, so your pet can come inside without dragging the yard in with them. Why it works Cleans paws in seconds, no bathtub required Gentle bristles are comfortable for sensitive paws Portable enough for the car, cottage, or trail Cuts down on muddy floors and furniture Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'dog foot washer, mess-free paw cleaning, muddy paw cleaner, portable paw washer, post-walk cleanup', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/fd0eeb26447b95cef933c2ab73b0.png?v=1785000451', 19.99, 19.99, 1, 1),
(8003766452314, 'Oversized Cat Bowl – Non-Slip Plastic Pet Food Dish', 'pet-bowl', 'https://kindred-pets-store.myshopify.com/products/pet-bowl', 'Feeding & Litter Supplies', 'Some cats step back from their bowl before they''ve even finished eating. A wide, shallow design keeps whiskers from brushing the sides, so mealtime stops being uncomfortable and starts being easy. Why it works Reduces whisker fatigue and food-pushing Non-slip base keeps the bowl steady mid-meal Wide shape works for wet or dry food Easy to wash after every use Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Feeding & Litter Supplies', 'cat mealtime comfort, non-slip cat bowl, oversized pet bowl, whisker fatigue bowl, wide shallow cat dish', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/5ec8f1034bac99e55856fa5024b4.png?v=1785000441', 5.99, 5.99, 1, 1),
(8003765698650, 'Kindred Chew & Squeak Toy', 'pet-molar-long-lasting-latex-sounding-toy', 'https://kindred-pets-store.myshopify.com/products/pet-molar-long-lasting-latex-sounding-toy', 'Dog & Cat Toys', 'A simple chew-and-play toy for dogs who like to gnaw, chase, and squeak. This latex toy combines a chewable shape with a built-in squeaker for everyday play. Choose the dolphin or penguin design your dog will enjoy. Before you order Choose between the Dolphin and Penguin designs. Supervise chewing and play. Inspect the toy regularly and remove it if it becomes damaged or pieces become loose. Kindred Standard: clear product information and straightforward buying expectations. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Toys', 'chew toys for dogs, chewing dog toy, dog molar toy, dog teeth care toy, durable pet toy, interactive dog toy, latex dog toy, long-lasting pet toy, non-toxic dog toy, pet dental toy, pet molar toy, pet playtime toy, puppy chew toy, rubber dog toy, safe pet toy, sounding dog toy, squeaky pet toy, teething dog toy', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/90b0bea4496b83499f2c410603af.png?v=1785000438', 8.99, 8.99, 1, 1),
(8003185475674, 'Kindred Breathable Pet Travel Backpack', 'pet-breathable-travel-backpack', 'https://kindred-pets-store.myshopify.com/products/pet-breathable-travel-backpack', 'Pet Travel & Outdoor Gear', 'A breathable carrier for everyday trips with small pets. Mesh ventilation panels give your pet airflow and visibility while you carry them for errands, walks, and other outings. Choose your configuration Start with size: choose the size that matches your pet''s measurements and the carrier''s listed dimensions. Do not choose by breed alone. Then choose a color: the available colors share the same listed starting price. Your selected combination will determine the exact variant. Before you order Measure your pet before selecting a size. Check the product dimensions and weight suitability shown for your selected configuration. Make sure the carrier''s size and design are appropriate for your pet and intended use. What you''ll receive Your selected backpack configuration. Review the chosen color and size before adding it to cart. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Travel & Outdoor Gear', 'breathable pet carrier, cat travel backpack, dog travel carrier, mesh pet backpack, pet hiking gear', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/37b62c1e422e861fbb9ca367ae86.jpg?v=1784159244', 13.99, 13.99, 1, 1),
(8003185344602, 'Kindred Automatic Dog Ball Launcher — Hands-Free Fetch', 'automatic-tennis-ball-launcher', 'https://kindred-pets-store.myshopify.com/products/automatic-tennis-ball-launcher', 'Dog & Cat Toys', 'Give high-energy dogs more fetch without throwing every ball yourself. The Kindred Automatic Dog Ball Launcher sends tennis balls at adjustable distances for active indoor or outdoor play. Each listed variant includes 1 launcher + 3 balls . Why it earns its place in your routine Hands-free fetch: keeps the game going without constant throwing. Adjustable distance: choose a launch range that fits your space and your dog. Ready to play: each variant includes the launcher and three balls. Before you order Choose Orange or Green ; both are the same launcher package. Use in an appropriate open area and keep people and pets clear of the launch path. Supervise your dog during play and inspect the balls and launcher regularly for damage. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Toys', 'automatic ball launcher, fetch toy for dogs, hands-free dog toy, high-energy dog exercise, solo fetch toy', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/4da7c04b44019bdfb932193ca98e.jpg?v=1784159243', 59.99, 59.99, 1, 1),
(8003185246298, 'Kindred LED Paw Trimmer — Grooming Tool with Light', 'pets-paw-trimmer-w-led-light', 'https://kindred-pets-store.myshopify.com/products/pets-paw-trimmer-w-led-light', 'Grooming & Health', 'See your pet''s paws more clearly while you trim. The Kindred LED Paw Trimmer combines a grooming tool with an integrated light to help illuminate the area you''re working on. Choose the standard set or the set that includes a nail clipper. Choose your set Set: LED paw trimmer. Set with Nail Clipper: LED paw trimmer plus nail clipper. Before you order Introduce grooming gradually and work carefully around your pet''s paws. The LED helps with visibility; it does not replace proper grooming technique. Check the tools before use and stop if your pet becomes distressed. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Grooming & Health', 'dog nail trimmer, LED grooming tool, paw hair trimmer, paw trimmer with light, precision pet grooming', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/bf979d0840ffaca401011bcb194c.jpg?v=1784159245', 7.99, 9.99, 1, 1),
(8003184066650, 'Kindred Slow Feeder Bowl', 'slow-feeder-pet-bowl', 'https://kindred-pets-store.myshopify.com/products/slow-feeder-pet-bowl', 'Feeding & Litter Supplies', 'Make mealtime slower, calmer, and more engaging. Raised feeding ridges encourage pets to take smaller, more deliberate bites instead of rushing through their meal. Made for everyday mealtimes Raised ridges encourage slower eating Simple design that''s easy to use every day A more engaging alternative to a standard bowl If your pet has a diagnosed medical condition or specific feeding needs, consult your veterinarian for personalized advice. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Feeding & Litter Supplies', 'anti-bloat dog bowl, digestion support, interactive feeding bowl, puppy feeding tool, slow feeder bowl', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/b69196624bdeb1103300f5f18627.jpg?v=1784966888', 5.99, 5.99, 1, 1),
(8003183935578, 'Cooling Splash Pad for Pets: Beat the Summer Heat!', 'summer-inflatable-water-mat-for-pets', 'https://kindred-pets-store.myshopify.com/products/summer-inflatable-water-mat-for-pets', 'Pet Beds & Comfort', 'Some dogs would live outside all summer if their paws could handle it. This inflatable splash pad fills with water in minutes, giving your pet a low-impact way to cool off without a full pool setup in the yard. Why it works Quick to inflate and fill — ready before the heat sets in Gentle on paws, safe for puppies and seniors Easy to drain, dry, and fold away after use Keeps outdoor play going on the hottest days Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Beds & Comfort', 'dog splash pad, heat relief for pets, inflatable pet pool, outdoor pet water play, summer cooling mat', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/faf27b1d433b8843d06446ddee89.webp?v=1784966886', 7.99, 7.99, 1, 1),
(8027023769690, 'Kindred Lounge Hammock', 'cat-glass-sleeping-cat-hammock', 'https://kindred-pets-store.myshopify.com/products/cat-glass-sleeping-cat-hammock', 'Pet Beds & Comfort', 'A quiet window perch for cats who love a good view. The Kindred Lounge Hammock gives cats and small pets a dedicated elevated spot to rest, nap, and watch what''s happening outside. Before you order Choose Amber Yellow or Crystal Gray . Confirm that your window and mounting surface are suitable before installation. Check that the hammock is secure before allowing your pet to use it. Best for: cats and small pets that enjoy elevated resting spaces. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Cat Furniture', 'cat window hammock, Kindred Pets, suction cup cat perch, sunny cat bed, window cat seat', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/9e86ee4c4520ab56606c3bfc7f1d.jpg?v=1785000593', 19.99, 19.99, 1, 1),
(8019066323034, 'Kindred Adventure Harness', 'dog-backpack-harness', 'https://kindred-pets-store.myshopify.com/products/dog-backpack-harness', 'Dog Walking Essentials', 'Made for walks that turn into adventures. The Kindred Adventure Harness keeps everyday essentials close with a built-in pouch, giving you a practical way to carry small essentials on walks and outdoor trips. Ready for everyday exploring Built-in storage pouch Designed for walks and outdoor use Multiple colors and sizes Choose the size carefully using your dog''s measurements before ordering. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Dog Harnesses', 'adventure dog harness, dog backpack harness, dog harness with pouch, hiking dog gear, Kindred Pets', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/40c3e2a74502973d8b2a954fcc74.png?v=1785000574', 17.99, 17.99, 1, 1),
(8018183094362, 'Nylon Leash For Dogs', 'nylon-pup-set', 'https://kindred-pets-store.myshopify.com/products/nylon-pup-set', 'Dog Walking Essentials', 'The gear you reach for every single day should feel as good as it looks. This collar-and-lead set is built for daily walks, made to last, and finished in colors that fit your dog''s personality. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Dog Collars and Leashes', 'dog collar and leash set, durable pet gear, everyday dog leash, Kindred Pets, nylon dog collar', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/a918311d46938f201c9ba892b1c4.jpg?v=1785000531', 11.99, 11.99, 1, 1),
(8003765174362, 'Kindred Pawprint Keepsake Kit', 'pet-pawprint-frame-diy', 'https://kindred-pets-store.myshopify.com/products/pet-pawprint-frame-diy', 'Pet Memorial and Keepsakes', 'One impression, one moment, kept forever. This simple at-home kit captures your pet''s paw print so you''ll have something to hold onto long after the muddy walks and shedding season — a small, lasting piece of them. What''s inside Non-toxic, quick-dry impression clay Ready-to-hang frame (White or Black) Step-by-step guide — no mess, no mistakes How it works Press your pet''s paw gently into the clay Let it air-dry — no oven, no baking Set it in the frame and display it anywhere Whether you''re welcoming a new puppy, marking a milestone, or holding onto a memory that matters, this kit turns a few quiet minutes with your pet into something you''ll keep for years. Kindred Pets — thoughtfully made for the moments that matter. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Memorial and Keepsakes', 'Kindred Pets, paw print kit, pawprint frame DIY, pet keepsake, pet memorial gift', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/ea39c2314988b559ed25b05616ec.png?v=1785000438', 11.99, 11.99, 1, 1),
(8003765928026, 'Kindred Window Lounge Hammock', 'comfortable-pet-hammock', 'https://kindred-pets-store.myshopify.com/products/comfortable-pet-hammock', 'Pet Beds & Comfort', 'A quiet window perch for cats and small pets. The Kindred Window Lounge Hammock creates an elevated place to rest, watch the room, and settle comfortably without taking up floor space. Choose your version Color: choose the finish you prefer. Packaging: the available packaging options are listed as separate variants. Packaging does not change the hammock itself. Before you order: check your window/surface compatibility and installation requirements carefully before purchasing. Make sure the mounting method is suitable for your surface and pet. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Cat Furniture', 'breathable pet lounge, cat hammock, elevated cat bed, Kindred Pets, small pet hammock', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/397af495427c8902bae56b61917a.png?v=1785000439', 13.99, 16.99, 1, 1),
(8003765567578, 'Kindred Warm Cat Nest', 'warm-cat-nest', 'https://kindred-pets-store.myshopify.com/products/warm-cat-nest', 'Pet Beds & Comfort', 'Cats don''t pick the biggest spot in the house — they pick the warmest, safest one. This arctic-velvet nest traps body heat and wraps around them like a hug, giving your cat a retreat that''s entirely their own. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Cat Beds', 'arctic velvet cat nest, cozy cat bed, indoor cat bed, Kindred Pets, warm cat bed', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/4c2079a04fb39965effd17598927.png?v=1785000437', 24.99, 24.99, 1, 1),
(8003763765338, 'CozyKin Plush Pet Bed', 'cozyplush-pet-bed', 'https://kindred-pets-store.myshopify.com/products/cozyplush-pet-bed', 'Pet Beds & Comfort', 'Some pets have a spot. This is it. Thick, ultra-soft filling holds its shape night after night, so the place they choose to curl up becomes the place they always choose. Machine washable, built for real life with real pets. Create the Ultimate Comfort Zone! For versatile comfort at home and on the go, pair this with our Portable Elevated Foldable Pet Bed . Perfect for every adventure and every nap! Unwavering Comfort & Quality Crafted with premium, durable materials for lasting comfort and support. Easy to clean and maintain, and backed by our 100% Satisfaction Guarantee for your peace of mind. Ships in 1–2 business days · Arrives in 7–15 business days.', 'Pet Beds', 'cozy dog bed, Kindred Pets, machine washable pet bed, plush pet bed, soft cat bed', 'https://cdn.shopify.com/s/files/1/0748/0822/9978/files/e4a50d794a13b1160b991c1a169d.png?v=1785000431', 39.99, 39.99, 1, 1);
